local SandCasterMaker = {}
local PRODUCTS = {
    iron_sandcaster = { name = "Železni peskalni ulitev", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni peskalni ulitev za livarje." },
    bronze_sandcaster = { name = "Bronast peskalni ulitev", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast peskalni ulitev za livarje." },
    silver_sandcaster = { name = "Srebrn peskalni ulitev", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn peskalni ulitev za livarje." },
    gilded_sandcaster = { name = "Pozlačen peskalni ulitev", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen peskalni ulitev za livarje." },
    jewel_set_sandcaster = { name = "Draguljast peskalni ulitev", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast peskalni ulitev za livarje." },
    royal_sovereign_sandcaster = { name = "Kraljevski suveren peskalni ulitev", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren peskalni ulitev z biseri za krono." },
}
local BUILDINGS = {
    sandcaster_workshop = { name = "Sandcaster delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sandcaster_house = { name = "Sandcaster hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sandcaster_atelier = { name = "Mojstrski sandcaster atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sandcaster_palace = { name = "Suverena sandcaster palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SandCasterMaker.ironStock = 14; SandCasterMaker.bronzeStock = 12; SandCasterMaker.woodStock = 14; SandCasterMaker.leatherStock = 10; SandCasterMaker.silverStock = 8; SandCasterMaker.goldStock = 6; SandCasterMaker.jewelStock = 4; SandCasterMaker.pearlStock = 4
SandCasterMaker.productStock = {}; SandCasterMaker.buildings = {}; SandCasterMaker.maker = nil; SandCasterMaker.activeMaking = {}; SandCasterMaker.totalProducts = 0; SandCasterMaker.dayTimer = 0
function SandCasterMaker.init() SandCasterMaker.ironStock=14; SandCasterMaker.bronzeStock=12; SandCasterMaker.woodStock=14; SandCasterMaker.leatherStock=10; SandCasterMaker.silverStock=8; SandCasterMaker.goldStock=6; SandCasterMaker.jewelStock=4; SandCasterMaker.pearlStock=4; SandCasterMaker.productStock={}; SandCasterMaker.buildings={}; SandCasterMaker.maker=nil; SandCasterMaker.activeMaking={}; SandCasterMaker.totalProducts=0; SandCasterMaker.dayTimer=0; print("[SandCasterMaker] Royal Sand Caster Maker System initialized (6 products, 4 buildings)") end
function SandCasterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SandCasterMaker.maker={name=n or ("Peskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peskar najet: %s (spretnost: %d)",SandCasterMaker.maker.name,s),"success") end; return true end
function SandCasterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SandCasterMaker.build(id) local ok,e=SandCasterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SandCasterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SandCasterMaker.getQualityBonus() local b=0; for _,bd in ipairs(SandCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SandCasterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SandCasterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SandCasterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SandCasterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SandCasterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SandCasterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SandCasterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SandCasterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SandCasterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SandCasterMaker.buildings==0 then return false,"Potrebna peskalna delavnica" end; if not SandCasterMaker.maker then return false,"Potreben peskar" end; return true end
function SandCasterMaker.make(pt,qty) qty=qty or 1; local ok,e=SandCasterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SandCasterMaker.ironStock=SandCasterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SandCasterMaker.bronzeStock=SandCasterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SandCasterMaker.woodStock=SandCasterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SandCasterMaker.leatherStock=SandCasterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SandCasterMaker.silverStock=SandCasterMaker.silverStock-d.silverCost*qty end; if d.goldCost then SandCasterMaker.goldStock=SandCasterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SandCasterMaker.jewelStock=SandCasterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SandCasterMaker.pearlStock=SandCasterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SandCasterMaker.maker then t=math.max(1,t-math.floor(SandCasterMaker.maker.skill/13)) end; table.insert(SandCasterMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SandCasterMaker.completeMaking(m) local q=1.0+(SandCasterMaker.getQualityBonus()/100); if SandCasterMaker.maker then q=q+(SandCasterMaker.maker.skill/140) end; q=math.min(2.5,q); SandCasterMaker.productStock[m.productType]=(SandCasterMaker.productStock[m.productType] or 0)+m.quantity; SandCasterMaker.totalProducts=SandCasterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SandCasterMaker.maker then SandCasterMaker.maker.itemsMade=SandCasterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SandCasterMaker.maker.skill=math.min(100,SandCasterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peskar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function SandCasterMaker.update(dt) if not _G.state then return end; SandCasterMaker.dayTimer=SandCasterMaker.dayTimer+dt; if SandCasterMaker.dayTimer>=30 then SandCasterMaker.dayTimer=0; for i=#SandCasterMaker.activeMaking,1,-1 do local m=SandCasterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SandCasterMaker.completeMaking(m); table.remove(SandCasterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SandCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SandCasterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SandCasterMaker.getStats() return {ironStock=SandCasterMaker.ironStock,bronzeStock=SandCasterMaker.bronzeStock,woodStock=SandCasterMaker.woodStock,leatherStock=SandCasterMaker.leatherStock,silverStock=SandCasterMaker.silverStock,goldStock=SandCasterMaker.goldStock,jewelStock=SandCasterMaker.jewelStock,pearlStock=SandCasterMaker.pearlStock,productStock=SandCasterMaker.productStock,numBuildings=#SandCasterMaker.buildings,hasMaker=SandCasterMaker.maker~=nil,makerName=SandCasterMaker.maker and SandCasterMaker.maker.name or "—",makerSkill=SandCasterMaker.maker and SandCasterMaker.maker.skill or 0,activeMaking=#SandCasterMaker.activeMaking,totalProducts=SandCasterMaker.totalProducts} end
return SandCasterMaker
